// UI Component Composite Implementation
interface UIComponent {
  render(): string;
  getType(): string;
}

class Button implements UIComponent {
  constructor(private text: string) {}

  render(): string {
    return `<button>${this.text}</button>`;
  }

  getType(): string {
    return 'Button';
  }
}

class Container implements UIComponent {
  private components: UIComponent[] = [];

  constructor(private tag: string) {}

  add(component: UIComponent): void {
    this.components.push(component);
  }

  render(): string {
    const content = this.components.map(c => c.render()).join('');
    return `<${this.tag}>${content}</${this.tag}>`;
  }

  getType(): string {
    return 'Container';
  }
}

// Expression Tree Composite Implementation
abstract class Expression {
  abstract evaluate(): number;
  abstract toString(): string;
}

class Number extends Expression {
  constructor(private value: number) {
    super();
  }

  evaluate(): number {
    return this.value;
  }

  toString(): string {
    return this.value.toString();
  }
}

class BinaryOperation extends Expression {
  constructor(
    private left: Expression,
    private operator: string,
    private right: Expression
  ) {
    super();
  }

  evaluate(): number {
    const leftVal = this.left.evaluate();
    const rightVal = this.right.evaluate();

    switch (this.operator) {
      case '+': return leftVal + rightVal;
      case '-': return leftVal - rightVal;
      case '*': return leftVal * rightVal;
      case '/': return leftVal / rightVal;
      default: throw new Error(`Unknown operator: ${this.operator}`);
    }
  }

  toString(): string {
    return `(${this.left.toString()} ${this.operator} ${this.right.toString()})`;
  }
}

